void abort(void);
void exit(int);

long double ll_to_ld(long long n) { return n; }

long long ld_to_ll(long double n) { return n; }

int main(void) {
  long long n;

  if (ll_to_ld(10LL) != 10.0)
    abort();

  if (ld_to_ll(10.0) != 10)
    abort();

  exit(0);
}


